def is_exotic(n):
    if n % 2 != 0:
        root = int(n**0.5)
        return root * root == n
    else:
        s = 0
        m = n
        while m % 2 == 0:
            s += 1
            m //= 2
        if s % 2 == 0:
            return False
        root = int(m**0.5)
        return root * root == m

exotics = []
for n in range(1, 20000):
    if is_exotic(n):
        exotics.append(n)

print(f"132nd: {exotics[131]}")

